esqlQuery.esql:
TS metrics-supabase.metrics.otel-*
// http_status_codes_total is a counter, one series per status code and route.
// Per-aggregation WHERE splits server errors from total requests in a single pass, so both
// sides of the ratio come from the same buckets. 4xx is carried as context only: bad
// passwords and expired tokens are routine auth traffic, not service failures.
| STATS
    `Server Errors` = SUM(INCREASE(http_status_codes_total)) WHERE attributes.code LIKE "5*",
    `Client Errors` = SUM(INCREASE(http_status_codes_total)) WHERE attributes.code LIKE "4*",
    `Requests` = SUM(INCREASE(http_status_codes_total))
  BY resource.attributes.supabase_project_ref
// Volume floor: a ratio over a handful of requests is noise, not signal.
| WHERE `Requests` >= 20
// The 5xx series does not exist until a 5xx occurs, so substitute zero for null.
| EVAL `Server Error %` = ROUND(CASE(`Server Errors` IS NULL, 0.0, `Server Errors`) / `Requests` * 100, 2)
// 5% of requests failing. Lower on high-traffic projects.
| WHERE `Server Error %` >= 5
| SORT `Server Error %` DESC
